export class DoctorOrchestrator implements IEngine {
  public readonly name = "DoctorOrchestrator";

  async run(context: Context): Promise<void> {
    const engines = [
      new ReasoningEngine(),
      new ProjectBrainEngine(),
      new AIRequirementEngine(),
      new RequirementRefinementEngine(),
      new BusinessRuleEngine(),
      new ArchitectureBuilder(),
      new ArchitectureDecisionEngine(),
      new ModulePlannerEngine(),
      new DependencyResolverEngine(),
      new SourceGeneratorEngine(),
      new CodeAssemblerEngine(),
      new ProjectScaffolder(),
      new TaskGraphEngine(),
      new SchedulerEngine(),
      new WorkerEngine(),
      new ProgressEngine(),
      new BackendGenerator(),
      new FrontendGenerator(),
      new DatabaseGenerator(),
      new AuthenticationGenerator(),
      new OpenApiGenerator(),
      new DockerGenerator(),
      new DeploymentGenerator(),
      new DocumentationGenerator(),
      new BuildEngine(),
      new CompileEngine(),
      new CompileMonitorEngine(),
      new RepairCoordinator(),
      new RepairLoopEngine(),
      new RefactorEngine(),
      new TestEngine(),
      new TestMonitorEngine(),
      new SelfHealingEngine(),
      new DecisionEngine(),
      new ResumeEngine(),
      new CheckpointEngine(),
      new VerificationEngine(),
      new SecurityScannerEngine(),
      new PerformanceAnalyzerEngine(),
      new PackageEngine(),
      new ReleaseEngine(),
      new DeploymentPreparationEngine(),
      new ProjectValidationEngine(),
      new QualityGateEngine(),
      new MetricsEngine(),
      new NotificationEngine(),
      new AuditEngine(),
      new DocumentationBuilderEngine(),
      new ReleaseBuilderEngine(),
      new VersionManagerEngine(),
      new PackagePublisherEngine(),
      new LearningEngine(),
      new KnowledgeBaseEngine(),
      new ExperienceEngine(),
      new OptimizationEngine(),
    ];

    for (const engine of engines) {
      await engine.run(context);
    }

    const history = new HistoryEngine(context.projectRoot);
    history.save(context, 0);
    const certificateEngine = new CertificationEngine();
    await certificateEngine.run(context);
  }
}

import fs from "node:fs/promises";
import path from "node:path";
import type { Context } from "../../core/Context.js";
import type { IEngine } from "../../core/IEngine.js";
import { ArtifactPipeline } from "../../artifacts/ArtifactPipeline.js";

export interface RequirementOutput {
  idea: string;
  modules: string[];
  actors: string[];
  businessRules: string[];
  permissions: string[];
  workflows: string[];
}

export class AIRequirementEngine implements IEngine {
  public readonly name = "AIRequirementEngine";

  async run(context: Context): Promise<void> {
    const requirementIdea = typeof context.metadata?.idea === "string" ? context.metadata.idea : context.projectName;
    const requirements: RequirementOutput = {
      idea: requirementIdea,
      modules: ["Core", "API", "UI", "Tests"],
      actors: ["Admin", "User"],
      businessRules: ["Users must authenticate", "Only admins can manage roles"],
      permissions: ["read", "write", "admin"],
      workflows: ["Login", "Create Record", "Approve Request"],
    };

    const pipeline = new ArtifactPipeline(context.projectRoot);
    await pipeline.run(context, [{
      id: "requirements-json",
      name: "requirements-json",
      templatePath: path.join(context.projectRoot, "templates", "requirement.json.tpl"),
      outputPath: path.join(context.projectRoot, "requirements", "requirement.json"),
      variables: {
        idea: requirements.idea,
        modules: requirements.modules.join(","),
        actors: requirements.actors.join(","),
        businessRules: requirements.businessRules.join(","),
        permissions: requirements.permissions.join(","),
        workflows: requirements.workflows.join(","),
      },
    }]);

    context.metadata = {
      ...context.metadata,
      requirements,
    } as typeof context.metadata & { requirements?: RequirementOutput };
  }
}

import type { Context } from "../core/Context.js";
import { ArtifactGenerator, type ArtifactSpec } from "./ArtifactGenerator.js";
import { TaskQueue } from "./TaskQueue.js";

export class ArtifactPipeline {
  constructor(private readonly workspaceRoot: string) {}

  async run(context: Context, specs: ArtifactSpec[]): Promise<void> {
    const generator = new ArtifactGenerator(this.workspaceRoot);
    const queue = new TaskQueue<ArtifactSpec>();
    const shouldSkipWrites = context.repairOptions?.dryRun === true;

    for (const spec of specs) {
      queue.enqueue(spec.id, spec);
    }

    await queue.run(async (spec) => {
      if (shouldSkipWrites) {
        const metadata = context.metadata as typeof context.metadata & { artifacts?: ArtifactSpec[] };
        metadata.artifacts = [...(metadata.artifacts ?? []), spec];
        return;
      }

      await generator.generate(spec, context);
      const metadata = context.metadata as typeof context.metadata & { artifacts?: ArtifactSpec[] };
      metadata.artifacts = [...(metadata.artifacts ?? []), spec];
    });

    context.metadata = {
      ...context.metadata,
      artifacts: specs,
      taskQueue: {
        progress: queue.getProgress(),
        logs: queue.getLogs(),
      },
    } as typeof context.metadata & { artifacts?: ArtifactSpec[]; taskQueue?: unknown };
  }
}

import fs from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";
import type { Context } from "../core/Context.js";

export interface ArtifactSpec {
  id: string;
  name: string;
  templatePath: string;
  outputPath: string;
  variables: Record<string, string>;
}

export interface ArtifactGenerationResult {
  status: "written" | "skipped";
  outputPath: string;
  templatePath: string;
  backupPath?: string;
}

export class ArtifactGenerator {
  constructor(private readonly workspaceRoot: string) {}

  async generate(spec: ArtifactSpec, context?: Context): Promise<ArtifactGenerationResult> {
    const templateContent = await this.readTemplate(spec.templatePath);
    const renderedContent = this.renderTemplate(templateContent, spec.variables);
    const contentWithMetadata = this.embedMetadata(renderedContent, spec.outputPath, context);

    await fs.mkdir(path.dirname(spec.outputPath), { recursive: true });

    try {
      await fs.access(spec.outputPath);
      const existing = await fs.readFile(spec.outputPath, "utf8");
      if (existing === contentWithMetadata) {
        return { status: "skipped", outputPath: spec.outputPath, templatePath: spec.templatePath };
      }

      const backupPath = `${spec.outputPath}.bak`;
      await fs.copyFile(spec.outputPath, backupPath);
      await fs.writeFile(spec.outputPath, contentWithMetadata, "utf8");
      return { status: "written", outputPath: spec.outputPath, templatePath: spec.templatePath, backupPath };
    } catch {
      await fs.writeFile(spec.outputPath, contentWithMetadata, "utf8");
      return { status: "written", outputPath: spec.outputPath, templatePath: spec.templatePath };
    }
  }

  private async readTemplate(templatePath: string): Promise<string> {
    try {
      return await fs.readFile(templatePath, "utf8");
    } catch {
      const currentFile = fileURLToPath(import.meta.url);
      const bundledTemplatePath = path.resolve(path.dirname(currentFile), "../templates", path.basename(templatePath));
      return await fs.readFile(bundledTemplatePath, "utf8");
    }
  }

  private renderTemplate(template: string, variables: Record<string, string>): string {
    return template.replace(/\{\{(.*?)\}\}/g, (_match, key: string) => {
      const trimmed = key.trim();
      return variables[trimmed] ?? "";
    });
  }

  private embedMetadata(content: string, outputPath: string, context?: Context): string {
    if (!context) {
      return content;
    }

    const metadata = this.buildArtifactMetadata(context);
    const extension = path.extname(outputPath).toLowerCase();

    if (extension === ".json") {
      try {
        const parsed = JSON.parse(content);
        if (Array.isArray(parsed)) {
          return JSON.stringify({ metadata, entries: parsed }, null, 2);
        }
        return JSON.stringify({ ...parsed, metadata }, null, 2);
      } catch {
        // fall back to a metadata-prefixed text block
      }
    }

    if (extension === ".md" || extension === ".txt") {
      const block = ``;
      return `${block}\n\n${content}`;
    }

    return content;
  }

  private buildArtifactMetadata(context: Context): Record<string, unknown> {
    const metadata = context.metadata as Record<string, unknown>;
    const results = Array.isArray(metadata.benchmarkResult) ? (metadata.benchmarkResult as Array<{ score?: number }> | undefined) ?? [] : [];
    const benchmarkScore = results.length ? results.reduce((sum, item) => sum + (item.score ?? 0), 0) / results.length : Number((metadata.benchmarkScore as number | undefined) ?? 0);
    const qualityScore = typeof metadata.qualityScore === "object" && metadata.qualityScore && "overallScore" in metadata.qualityScore
      ? Number((metadata.qualityScore as { overallScore?: number }).overallScore ?? 0)
      : Number((metadata.qualityScore as number | undefined) ?? 0);
    const validationScore = typeof metadata.validationReport === "object" && metadata.validationReport && "benchmarkScore" in metadata.validationReport
      ? Number((metadata.validationReport as { benchmarkScore?: number }).benchmarkScore ?? 0)
      : Number((metadata.validationScore as number | undefined) ?? 0);
    const knowledgeVersion = String((metadata.knowledgeVersion as string | undefined) ?? "1.0.0");

    return {
      projectId: String((metadata.projectId as string | undefined) ?? context.projectName),
      projectName: context.projectName,
      runtimeId: String((metadata.runtimeId as string | undefined) ?? "satset-doctor"),
      timestamp: new Date().toISOString(),
      benchmarkScore,
      qualityScore,
      validationScore,
      knowledgeVersion,
    };
  }
}

export interface TaskQueueItem<T> {
  id: string;
  payload: T;
  attempts: number;
}

export interface TaskQueueProgress {
  completed: number;
  total: number;
  pending: number;
  etaMs: number;
}

export class TaskQueue<T> {
  private readonly items: TaskQueueItem<T>[] = [];
  private readonly completed: Array<{ id: string; payload: T }> = [];
  private readonly logs: Array<{ id: string; message: string }> = [];

  enqueue(id: string, payload: T): void {
    this.items.push({ id, payload, attempts: 0 });
  }

  async run(handler: (payload: T, item: TaskQueueItem<T>) => Promise<void>): Promise<void> {
    while (this.items.length > 0) {
      const item = this.items.shift();
      if (!item) {
        break;
      }

      try {
        await handler(item.payload, item);
        this.completed.push({ id: item.id, payload: item.payload });
        this.logs.push({ id: item.id, message: "completed" });
      } catch (error) {
        item.attempts += 1;
        this.logs.push({ id: item.id, message: error instanceof Error ? error.message : String(error) });
        if (item.attempts < 3) {
          this.items.push(item);
        }
      }
    }
  }

  getProgress(): TaskQueueProgress {
    return {
      completed: this.completed.length,
      total: this.completed.length + this.items.length,
      pending: this.items.length,
      etaMs: this.items.length * 1000,
    };
  }

  getLogs(): Array<{ id: string; message: string }> {
    return [...this.logs];
  }
}

import path from "node:path";
import type { Context } from "../core/Context.js";
import type { IEngine } from "../core/IEngine.js";
import { ArtifactPipeline } from "../artifacts/ArtifactPipeline.js";

export interface ReasoningOutput {
  intent: string;
  domain: string;
  requirements: string[];
  entities: string[];
  relationships: string[];
  useCases: string[];
  apiSpec: string[];
  databaseDesign: string[];
  screenSpecs: string[];
}

export class ReasoningEngine implements IEngine {
  public readonly name = "ReasoningEngine";

  async run(context: Context): Promise<void> {
    const rawIdea = typeof context.metadata?.idea === "string" ? context.metadata.idea : context.projectName;
    const output: ReasoningOutput = {
      intent: `Build ${rawIdea}`,
      domain: "enterprise",
      requirements: ["Authentication", "Core workflows", "Audit trail"],
      entities: ["User", "Project", "AuditEntry"],
      relationships: ["Project has many AuditEntry", "User owns Project"],
      useCases: ["Create project", "Approve request"],
      apiSpec: ["GET /projects", "POST /projects"],
      databaseDesign: ["Prisma schema", "Migrations"],
      screenSpecs: ["Dashboard", "Settings"],
    };

    const pipeline = new ArtifactPipeline(context.projectRoot);
    const specs = [
