export interface BuildMetrics {
  packageManager: "pnpm" | "npm" | "yarn" | "unknown";
  installExitCode: number | null;
  compileExitCode: number | null;
  compileTimeMs: number;
  diagnostics: string[];
  logs: string[];
}

export class BuildEngine implements IEngine {
  public readonly name = "BuildEngine";
  constructor(private readonly executor = new CommandExecutor()) {}

  async run(context: Context): Promise<void> {
    const metrics: BuildMetrics = {
      packageManager: await this.detectPackageManager(context.projectRoot),
      installExitCode: null,
      compileExitCode: null,
      compileTimeMs: 0,
      diagnostics: [],
      logs: [],
    };

    const pipeline = new ArtifactPipeline(context.projectRoot);
    await pipeline.run(context, [{
      id: "build-progress",
      name: "build-progress",
      templatePath: path.join(context.projectRoot, "templates", "build-progress.json.tpl"),
      outputPath: path.join(context.projectRoot, ".progress.json"),
      variables: {
        currentStage: "build",
        progress: "20",
        currentTask: "installing dependencies",
        estimatedRemaining: "30s",
      },
    }]);

    const installResult = await this.executor.pnpm(["install", "--ignore-scripts"], context.projectRoot);
    metrics.installExitCode = installResult.exitCode;
    metrics.logs.push(installResult.stdout, installResult.stderr);

    const startedAt = Date.now();
    const compileResult = await this.executor.pnpm(["tsc", "-p", "tsconfig.json", "--noEmit"], context.projectRoot);
    metrics.compileExitCode = compileResult.exitCode;
    metrics.compileTimeMs = Date.now() - startedAt;
    metrics.logs.push(compileResult.stdout, compileResult.stderr);

    if (compileResult.exitCode !== 0) {
      metrics.diagnostics.push(...compileResult.stderr.split(/\n+/).filter(Boolean).slice(0, 10));
    }

    context.metadata = {
      ...context.metadata,
      build: metrics,
    } as typeof context.metadata & { build?: BuildMetrics };
  }

  private async detectPackageManager(root: string): Promise<BuildMetrics["packageManager"]> {
    try {
      await fs.access(path.join(root, "pnpm-lock.yaml"));
      return "pnpm";
    } catch {
      return "unknown";
    }
  }
}

import { spawn } from "node:child_process";

export interface CommandExecutionResult {
  command: string;
  args: string[];
  exitCode: number | null;
  stdout: string;
  stderr: string;
  durationMs: number;
}

export class CommandExecutor {
  public async run(command: string, args: string[] = [], options: { cwd?: string; env?: NodeJS.ProcessEnv } = {}): Promise<CommandExecutionResult> {
    const startedAt = Date.now();
    const child = spawn(command, args, {
      cwd: options.cwd ?? process.cwd(),
      env: options.env ?? process.env,
      shell: true,
      stdio: ["ignore", "pipe", "pipe"],
    });

    let stdout = "";
    let stderr = "";

    child.stdout?.on("data", (chunk) => {
      stdout += chunk.toString();
    });

    child.stderr?.on("data", (chunk) => {
      stderr += chunk.toString();
    });

    const exitCode = await new Promise<number | null>((resolve, reject) => {
      child.once("error", reject);
      child.once("close", resolve);
    });

    return {
      command,
      args,
      exitCode,
      stdout,
      stderr,
      durationMs: Date.now() - startedAt,
    };
  }

  public async pnpm(args: string[], cwd?: string): Promise<CommandExecutionResult> {
    return this.run("pnpm", args, { cwd });
  }

  public async npm(args: string[], cwd?: string): Promise<CommandExecutionResult> {
    return this.run("npm", args, { cwd });
  }

  public async npx(args: string[], cwd?: string): Promise<CommandExecutionResult> {
    return this.run("npx", args, { cwd });
  }

  public async prisma(args: string[], cwd?: string): Promise<CommandExecutionResult> {
    return this.run("prisma", args, { cwd });
  }

  public async git(args: string[], cwd?: string): Promise<CommandExecutionResult> {
    return this.run("git", args, { cwd });
  }

  public async docker(args: string[], cwd?: string): Promise<CommandExecutionResult> {
    return this.run("docker", args, { cwd });
  }

  public async turbo(args: string[], cwd?: string): Promise<CommandExecutionResult> {
    return this.run("turbo", args, { cwd });
  }

  public async next(args: string[], cwd?: string): Promise<CommandExecutionResult> {
    return this.run("next", args, { cwd });
  }

  public async node(args: string[], cwd?: string): Promise<CommandExecutionResult> {
    return this.run("node", args, { cwd });
  }

  public async tsc(args: string[], cwd?: string): Promise<CommandExecutionResult> {
    return this.run("tsc", args, { cwd });
  }

  public async eslint(args: string[], cwd?: string): Promise<CommandExecutionResult> {
    return this.run("eslint", args, { cwd });
  }

  public async prettier(args: string[], cwd?: string): Promise<CommandExecutionResult> {
