import fs from "node:fs";
import path from "node:path";
import type { HistoryComparison, HistoryRecord } from "./History.js";
import { HistorySerializer } from "./HistorySerializer.js";

export class HistoryRepository {
  private readonly root: string;
  private readonly serializer = new HistorySerializer();

  constructor(root: string) {
    this.root = root;
  }

  save(record: HistoryRecord): void {
    const historyDir = this.ensureHistoryDirectory(record.fingerprint.hash);
    const fileName = `scan-${record.scanId.padStart(6, "0")}.json`;
    const filePath = path.join(historyDir, fileName);
    fs.writeFileSync(filePath, this.serializer.serialize(record), "utf8");
  }

  load(scanId: string): HistoryRecord | null {
    const historyDirs = this.getFingerprintDirectories();
    for (const dir of historyDirs) {
      const filePath = path.join(dir, `scan-${scanId.padStart(6, "0")}.json`);
      if (fs.existsSync(filePath)) {
        return this.serializer.deserialize(fs.readFileSync(filePath, "utf8"));
      }
    }
    return null;
  }

  latest(): HistoryRecord | null {
    const historyDirs = this.getFingerprintDirectories();
    let latestRecord: HistoryRecord | null = null;

    for (const dir of historyDirs) {
      const files = fs.readdirSync(dir).filter((name) => /^scan-\d{6}\.json$/.test(name)).sort().reverse();
      if (files.length === 0) continue;
      const record = this.serializer.deserialize(fs.readFileSync(path.join(dir, files[0]), "utf8"));
      if (!latestRecord || new Date(record.timestamp) > new Date(latestRecord.timestamp)) {
        latestRecord = record;
      }
    }

    return latestRecord;
  }

  list(): HistoryRecord[] {
    const records: HistoryRecord[] = [];
    const historyDirs = this.getFingerprintDirectories();
    for (const dir of historyDirs) {
      const files = fs.readdirSync(dir).filter((name) => /^scan-\d{6}\.json$/.test(name)).sort();
      for (const file of files) {
        records.push(this.serializer.deserialize(fs.readFileSync(path.join(dir, file), "utf8")));
      }
    }
    return records;
  }

  compare(scanA: string, scanB: string): HistoryComparison | null {
    const recordA = this.load(scanA);
    const recordB = this.load(scanB);
    if (!recordA || !recordB) return null;

    const differences: Record<string, { a: unknown; b: unknown }> = {};
    const keys = new Set([...Object.keys(recordA), ...Object.keys(recordB)]);
    for (const key of keys) {
      const aValue = (recordA as unknown as Record<string, unknown>)[key];
      const bValue = (recordB as unknown as Record<string, unknown>)[key];
      if (JSON.stringify(aValue) !== JSON.stringify(bValue)) {
        differences[key] = { a: aValue, b: bValue };
      }
    }

    const issueKey = (issue: { id: string; message: string }) => `${issue.id}::${issue.message}`;
    const issueMapA = new Map(recordA.issues.map((issue) => [issueKey(issue), issue]));
    const issueMapB = new Map(recordB.issues.map((issue) => [issueKey(issue), issue]));

    const newIssues = recordB.issues.filter((issue) => !issueMapA.has(issueKey(issue)));
    const fixedIssues = recordA.issues.filter((issue) => !issueMapB.has(issueKey(issue)));
    const unchangedIssues = recordB.issues.filter((issue) => issueMapA.has(issueKey(issue)));

    const healthDelta = (recordB.health?.score ?? 0) - (recordA.health?.score ?? 0);
    const scoreDelta = healthDelta;
    const severityDelta = unchangedIssues.filter((issue) => {
      const previous = issueMapA.get(issueKey(issue));
      return previous ? previous.severity !== issue.severity : false;
    }).length;

    return {
      scanA,
      scanB,
      sameFingerprint: recordA.fingerprint.hash === recordB.fingerprint.hash,
      differences,
      newIssues,
      fixedIssues,
      unchangedIssues,
      healthDelta,
      scoreDelta,
      severityDelta,
    };
  }

  nextScanId(fingerprintHash: string): string {
    const historyDir = path.join(this.getHistoryRoot(), fingerprintHash);
    if (!fs.existsSync(historyDir)) {
      return "1";
    }

    const files = fs.readdirSync(historyDir).filter((name) => /^scan-\d{6}\.json$/.test(name));
    const highest = files
      .map((file) => Number(file.replace(/^scan-(\d{6})\.json$/, "$1")))
      .filter(Number.isFinite)
      .sort((a, b) => b - a)[0];

    return highest ? String(highest + 1) : "1";
  }

  private ensureHistoryDirectory(fingerprintHash: string): string {
    const historyRoot = this.getHistoryRoot();
    const fingerprintDir = path.join(historyRoot, fingerprintHash);
    if (!fs.existsSync(historyRoot)) {
      fs.mkdirSync(historyRoot, { recursive: true });
    }
    if (!fs.existsSync(fingerprintDir)) {
      fs.mkdirSync(fingerprintDir, { recursive: true });
    }
    return fingerprintDir;
  }

  private getHistoryRoot(): string {
    return path.join(this.root, ".history");
  }

  private getFingerprintDirectories(): string[] {
    const historyRoot = this.getHistoryRoot();
    if (!fs.existsSync(historyRoot)) return [];
    return fs.readdirSync(historyRoot)
      .map((name) => path.join(historyRoot, name))
      .filter((dir) => fs.statSync(dir).isDirectory());
  }
}

import stringify from "json-stable-stringify";
import type { HistoryRecord } from "./History.js";

export class HistorySerializer {
  serialize(record: HistoryRecord): string {
    const result = stringify(record as unknown as object, { space: 2 });
    return typeof result === "string" ? result : JSON.stringify(record, null, 2);
  }

  deserialize(content: string): HistoryRecord {
    return JSON.parse(content) as HistoryRecord;
  }
}

import crypto from "crypto";
import fs from "node:fs";
import path from "node:path";
import type { Context } from "./Context.js";

export interface ProjectFingerprint {
  framework: string | null;
  packageManager: string | null;
  workspace: boolean;
  typescript: string | null;
  react: string | null;
  next: string | null;
  prisma: string | null;
  tailwind: string | null;
  turbo: string | null;
  database: string | null;
  nodeVersion: string | null;
  dependencyCount: number;
  workspaceCount: number;
  trackedFileCount: number;
  trackedFilesHash: string;
  hash: string;
  signature: string;
}

export class ProjectFingerprintCalculator {
  public generate(context: Context): ProjectFingerprint {
    const metadata = context.metadata as Record<string, unknown>;

    const framework = this.getFramework(metadata);
    const packageManager = this.getPackageManager(metadata);
    const workspacePackages = this.getWorkspacePackages(metadata);
    const typescript = this.getVersion(metadata.typescript as Record<string, unknown> | null, "version");
    const react = this.getVersion(metadata.react as Record<string, unknown> | null, "reactVersion");
    const next = this.getVersion(metadata.next as Record<string, unknown> | null, "nextVersion");
    const prisma = this.getVersion(metadata.prisma as Record<string, unknown> | null, "prismaVersion");
    const tailwind = this.getVersion(metadata.tailwind as Record<string, unknown> | null, "version");
    const turbo = this.getVersion(metadata.turbo as Record<string, unknown> | null, "packageManager");
    const database = this.getDatabase(metadata);
    const nodeVersion = typeof context.nodeVersion === "string" ? context.nodeVersion : null;
    const dependencyCount = this.getDependencyCount(metadata);
    const workspaceCount = workspacePackages.length;
    const trackedFiles = this.collectMeaningfulFiles(context.projectRoot);
    const trackedFileCount = trackedFiles.length;
    const trackedFilesHash = this.createStableHash(trackedFiles);

    const fingerprintPayload = {
      framework,
      packageManager,
      workspace: workspaceCount > 0,
      typescript,
      react,
      next,
      prisma,
      tailwind,
      turbo,
      database,
      nodeVersion,
      dependencyCount,
      workspaceCount,
      trackedFileCount,
      trackedFilesHash,
    };

    const hash = this.createStableHash(fingerprintPayload);
    const signature = `${framework ?? "unknown"}:${packageManager ?? "unknown"}:${hash}`;

    return {
      ...fingerprintPayload,
      hash,
      signature,
    };
  }

  private getFramework(metadata: Record<string, unknown>): string | null {
    if (this.hasMetadata(metadata.next)) {
      return "next";
    }
    if (this.hasMetadata(metadata.react)) {
      return "react";
    }
    if (this.hasMetadata(metadata.tailwind)) {
      return "tailwind";
    }
    if (this.hasMetadata(metadata.turbo)) {
      return "turbo";
    }
    return null;
  }

  private getPackageManager(metadata: Record<string, unknown>): string | null {
    if (typeof metadata.packageManager === "string") {
      return metadata.packageManager;
    }
    const pnpm = metadata.pnpm as Record<string, unknown> | null;
    if (pnpm && typeof pnpm.packageManager === "string") {
      return pnpm.packageManager;
    }
    return null;
  }

  private getWorkspacePackages(metadata: Record<string, unknown>): string[] {
    const pnpm = metadata.pnpm as Record<string, unknown> | null;
    if (pnpm && Array.isArray(pnpm.workspacePackages)) {
      return pnpm.workspacePackages.map(String);
    }

    const packageJson = metadata.packageJson as Record<string, unknown> | null;
    if (!packageJson) {
      return [];
    }

    const workspaces = packageJson.workspaces;
    if (Array.isArray(workspaces)) {
      return workspaces.map(String);
    }
    if (workspaces && typeof workspaces === "object" && Array.isArray((workspaces as Record<string, unknown>).packages)) {
      return ((workspaces as Record<string, unknown>).packages as unknown[]).map(String);
    }

    return [];
  }

  private getVersion(metadata: Record<string, unknown> | null, key: string): string | null {
    if (!metadata || typeof metadata !== "object") {
      return null;
    }
    const value = metadata[key as keyof typeof metadata];
    return typeof value === "string" ? value : null;
  }

  private getDatabase(metadata: Record<string, unknown>): string | null {
    const prisma = metadata.prisma as Record<string, unknown> | null;
    if (prisma && this.getVersion(prisma, "prismaVersion")) {
      return "prisma";
    }

    const environment = metadata.environment as Record<string, unknown> | null;
    if (environment && environment.hasOwnProperty("hasDatabaseUrl") && environment.hasOwnProperty("hasSupabaseUrl")) {
      if (environment.hasOwnProperty("hasSupabaseUrl") && (environment.hasOwnProperty("hasSupabaseUrl") as unknown)) {
        return "supabase";
      }
      if (environment.hasOwnProperty("hasDatabaseUrl")) {
        return "database";
      }
    }

    return null;
  }

  private getDependencyCount(metadata: Record<string, unknown>): number {
    const dependencies = metadata.dependencies as Record<string, unknown> | null;
    if (dependencies && typeof dependencies.totalPackages === "number") {
      return dependencies.totalPackages;
    }
    return 0;
  }

  private collectMeaningfulFiles(projectRoot: string): Array<{ relativePath: string; hash: string }> {
    const trackedFiles: Array<{ relativePath: string; hash: string }> = [];
    const queue = [projectRoot];
    const ignoredDirectories = new Set([".git", ".history", ".next", ".turbo", ".cache", "node_modules", "dist", "build", "coverage", "out"]);
    const ignoredFiles = new Set([".DS_Store", "Thumbs.db", "package-lock.json", "npm-shrinkwrap.json", "yarn.lock", "pnpm-lock.yaml"]);
    const includedExtensions = new Set([".ts", ".tsx", ".js", ".jsx", ".mjs", ".cjs", ".json", ".yaml", ".yml", ".toml", ".prisma", ".env"]);
    const includedFiles = new Set(["package.json", "pnpm-workspace.yaml", "turbo.json", "tsconfig.json", "postcss.config.js", "postcss.config.cjs", "postcss.config.mjs", "postcss.config.ts", "tailwind.config.js", "tailwind.config.cjs", "tailwind.config.mjs", "tailwind.config.ts", "next.config.js", "next.config.cjs", "next.config.mjs", "next.config.ts"]);

    while (queue.length > 0) {
      const currentPath = queue.shift();
      if (!currentPath) continue;

      let entries: fs.Dirent[];
      try {
        entries = fs.readdirSync(currentPath, { withFileTypes: true });
      } catch {
        continue;
      }

      for (const entry of entries) {
        const absolutePath = path.join(currentPath, entry.name);
        if (entry.isDirectory()) {
          if (!ignoredDirectories.has(entry.name)) {
            queue.push(absolutePath);
          }
          continue;
        }

        if (entry.isFile()) {
          const relativePath = path.relative(projectRoot, absolutePath).split(path.sep).join("/");
          if (!relativePath || ignoredFiles.has(entry.name)) {
            continue;
          }

          const extension = path.extname(entry.name);
          const isIncludedByExtension = includedExtensions.has(extension);
          const isIncludedByName = includedFiles.has(entry.name) || entry.name.startsWith(".env") || entry.name.endsWith(".prisma");
          if (!isIncludedByExtension && !isIncludedByName) {
            continue;
          }

          const fileContent = fs.readFileSync(absolutePath, "utf8");
          trackedFiles.push({
            relativePath,
            hash: this.createStableHash({ path: relativePath, content: fileContent }),
          });
        }
      }
    }

    return trackedFiles.sort((left, right) => left.relativePath.localeCompare(right.relativePath));
  }

  private createStableHash(value: unknown): string {
    const stableString = this.stringifyStable(value);
    return crypto.createHash("sha256").update(stableString, "utf8").digest("hex");
  }

  private stringifyStable(value: unknown): string {
    if (value === null || typeof value !== "object") {
      return JSON.stringify(value);
    }

    if (Array.isArray(value)) {
      return `[${value.map((item) => this.stringifyStable(item)).join(",")} ]`;
    }

    const sortedKeys = Object.keys(value).sort();
    const entries = sortedKeys.map((key) => `${JSON.stringify(key)}:${this.stringifyStable((value as Record<string, unknown>)[key])}`);
    return `{${entries.join(",")}}`;
  }

  private hasMetadata(value: unknown): boolean {
    if (!value || typeof value !== "object") {
      return false;
    }

    if (Array.isArray(value)) {
      return value.length > 0;
    }

    return Object.keys(value).length > 0;
  }
}

import type { Context } from "../core/Context.js";
import { CompileEngine } from "../ai/engines/CompileEngine.js";
import { TestEngine } from "../ai/engines/TestEngine.js";
import { CompileResultParser, type CompileResult } from "./CompileResult.js";
import { ErrorClassifier } from "./ErrorClassifier.js";
import { PatchPlanner } from "./PatchPlanner.js";
import { PatchGenerator } from "./PatchGenerator.js";
import { PatchApplier } from "./PatchApplier.js";
import { DefaultRetryPolicy } from "./RetryPolicy.js";
import { ArtifactPipeline } from "../artifacts/ArtifactPipeline.js";
import path from "node:path";
import type { HistoryEngine } from "../history/HistoryEngine.js";
import type { CheckpointManager } from "./CheckpointManager.js";
import type { DashboardRuntime } from "./DashboardRuntime.js";
import type { EventBus } from "./EventBus.js";
import { BuildVerifier } from "./BuildVerifier.js";

export interface RepairIteration {
  attempt: number;
  compile: CompileResult;
  classifiedErrors: ReturnType<ErrorClassifier["classify"]>;
  patchPlans: ReturnType<PatchPlanner["plan"]>;
  patchResults: Awaited<ReturnType<PatchApplier["apply"]>>;
  status: "passed" | "failed";
}

export class RepairCoordinator {
  public readonly name = "RepairCoordinator";

  constructor(
    private readonly compileEngine: CompileEngine = new CompileEngine(),
    private readonly testEngine: TestEngine = new TestEngine(),
    private readonly errorClassifier: ErrorClassifier = new ErrorClassifier(),
    private readonly patchPlanner: PatchPlanner = new PatchPlanner(),
    private readonly patchGenerator: PatchGenerator = new PatchGenerator(),
    private readonly patchApplier: PatchApplier = new PatchApplier(),
    private readonly buildVerifier: BuildVerifier = new BuildVerifier(),
    private readonly retryPolicy: DefaultRetryPolicy = new DefaultRetryPolicy(),
    private readonly historyEngine?: HistoryEngine,
    private readonly checkpointManager?: CheckpointManager,
    private readonly dashboardRuntime?: DashboardRuntime,
    private readonly eventBus?: EventBus
  ) {}

  async run(context: Context): Promise<void> {
    const iterations: RepairIteration[] = [];
    const pipeline = new ArtifactPipeline(context.projectRoot);
    await pipeline.run(context, [{
      id: "repair-coordinator",
      name: "repair-coordinator",
      templatePath: path.join(context.projectRoot, "templates", "repair-progress.json.tpl"),
      outputPath: path.join(context.projectRoot, ".progress.json"),
      variables: {
        currentStage: "repair",
        progress: "60",
        currentTask: "repairing compile and test failures",
        estimatedRemaining: "20s",
      },
    }]);

    for (let attempt = 1; attempt <= this.retryPolicy.maxAttempts; attempt += 1) {
      const compileResult = await this.runCompile(context);
      const diagnostics = compileResult.diagnostics;
      const classifiedErrors = this.errorClassifier.classify(diagnostics);
      const patchPlans = this.patchPlanner.plan(diagnostics);
      const generatedPatches = await this.patchGenerator.generate(patchPlans, classifiedErrors, context.projectRoot);
      const patchResults = await this.patchApplier.apply(generatedPatches, context.projectRoot);
      await this.testEngine.run(context);
      const verificationResult = await this.buildVerifier.verify(context, compileResult);
      const status = verificationResult.compilePassed && verificationResult.testsPassed && verificationResult.verificationPassed ? "passed" : "failed";
      iterations.push({ attempt, compile: compileResult, classifiedErrors, patchPlans, patchResults, status });

      context.metadata = {
        ...context.metadata,
        repairIterations: iterations,
      } as typeof context.metadata & { repairIterations?: RepairIteration[] };

      this.historyEngine?.save(context, 0);
      await this.checkpointManager?.save(context, [], "repair");
      this.dashboardRuntime?.getSnapshot();
      this.eventBus?.emit({ type: "RepairIterationCompleted", timestamp: new Date().toISOString(), stage: "Repair", details: { attempt, status } });

      if (status === "passed") {
        break;
      }
    }
  }

  private async runCompile(context: Context): Promise<CompileResult> {
    await this.compileEngine.run(context);
    const compileState = context.metadata?.compile as { diagnostics?: string[]; exitCode?: number | null; stdout?: string; stderr?: string } | undefined;
    const stdout = compileState?.stdout ?? "";
    const stderr = compileState?.stderr ?? "";
    const diagnosticsText = [...(compileState?.diagnostics ?? []), stdout, stderr].join("\n");
    const diagnostics = CompileResultParser.parse(diagnosticsText);
    const succeeded = (compileState?.exitCode ?? 0) === 0 && diagnostics.filter((diagnostic) => diagnostic.severity === "error").length === 0;
    return {
      succeeded,
      exitCode: compileState?.exitCode ?? null,
      stdout,
      stderr,
      diagnostics,
      errorCount: diagnostics.filter((diagnostic) => diagnostic.severity === "error").length,
      warningCount: diagnostics.filter((diagnostic) => diagnostic.severity === "warning").length,
      infoCount: diagnostics.filter((diagnostic) => diagnostic.severity === "info").length,
    };
  }
}

import path from "node:path";

export type CompileDiagnosticSeverity = "error" | "warning" | "info";

export interface CompileDiagnostic {
  raw: string;
  file?: string;
  line?: number;
  column?: number;
  severity: CompileDiagnosticSeverity;
  code?: string;
  message: string;
}

export interface CompileResult {
  succeeded: boolean;
  exitCode: number | null;
  stdout: string;
  stderr: string;
  diagnostics: CompileDiagnostic[];
  errorCount: number;
  warningCount: number;
  infoCount: number;
}

export class CompileResultParser {
  static parse(output: string): CompileDiagnostic[] {
    return output
      .split(/\r?\n/)
      .map((line) => line.trim())
      .filter(Boolean)
      .map((line) => this.parseLine(line))
      .filter((diagnostic): diagnostic is CompileDiagnostic => diagnostic !== null);
  }

  private static parseLine(line: string): CompileDiagnostic | null {
    const fileMatch = line.match(/^(.*?)(?::(\d+))?(?::(\d+))?\s*[-–:]\s*(error|warning|info)\s*(TS\d+)?\s*:?\s*(.*)$/i);
    if (fileMatch) {
      const [, rawFile, rawLine, rawColumn, severityText, code, message] = fileMatch;
      const severity = this.toSeverity(severityText);
      const normalizedFile = rawFile.trim();
      const normalizedFilePath = normalizedFile && normalizedFile !== "error" && normalizedFile !== "warning" && normalizedFile !== "info"
        ? path.normalize(normalizedFile)
        : undefined;
      return {
        raw: line,
        file: normalizedFilePath,
        line: rawLine ? Number(rawLine) : undefined,
        column: rawColumn ? Number(rawColumn) : undefined,
        severity,
        code: code?.trim() || undefined,
        message: message?.trim() || line,
      };
    }

    const tsMatch = line.match(/(error|warning|info)\s+(TS\d+)?\s*:?\s*(.*)$/i);
    if (tsMatch) {
      const [, severityText, code, message] = tsMatch;
      return {
        raw: line,
        severity: this.toSeverity(severityText),
        code: code?.trim() || undefined,
        message: message?.trim() || line,
      };
    }

    return null;
  }

  private static toSeverity(value: string): CompileDiagnosticSeverity {
    const normalized = value.toLowerCase();
    if (normalized.includes("warning")) {
      return "warning";
    }
    if (normalized.includes("info")) {
      return "info";
    }
    return "error";
  }
}

import type { CompileDiagnostic } from "./CompileResult.js";

export type ErrorCategory = "typescript-config" | "missing-dependency" | "syntax" | "unknown";

export interface ClassifiedError {
  category: ErrorCategory;
  confidence: number;
  diagnostic: CompileDiagnostic;
  reason: string;
}

export class ErrorClassifier {
  classify(diagnostics: readonly CompileDiagnostic[]): ClassifiedError[] {
    return diagnostics.map((diagnostic) => this.classifyOne(diagnostic));
  }

  private classifyOne(diagnostic: CompileDiagnostic): ClassifiedError {
    const message = diagnostic.message.toLowerCase();
    if (message.includes("jsx") || message.includes("react/jsx-runtime")) {
      return { category: "missing-dependency", confidence: 0.95, diagnostic, reason: "JSX compilation requires the React runtime packages." };
    }
    if (message.includes("cannot find name") || message.includes("does not exist")) {
      return { category: "typescript-config", confidence: 0.8, diagnostic, reason: "TypeScript is missing ambient types or config for the referenced symbol." };
    }
    return { category: "unknown", confidence: 0.4, diagnostic, reason: "The diagnostic did not match a known repair pattern." };
  }
}

import path from "node:path";
import type { CompileDiagnostic } from "./CompileResult.js";

export interface PatchPlan {
  id: string;
  targetPath?: string;
  kind: "file-create" | "file-edit" | "dependency-install" | "command";
  summary: string;
  description: string;
  patch: string;
}

export class PatchPlanner {
  plan(diagnostics: readonly CompileDiagnostic[]): PatchPlan[] {
    return diagnostics
      .map((diagnostic) => this.planDiagnostic(diagnostic))
      .filter((plan): plan is PatchPlan => plan !== undefined);
  }

  private planDiagnostic(diagnostic: CompileDiagnostic): PatchPlan | undefined {
    const message = diagnostic.message.toLowerCase();
    if (message.includes("jsx") || message.includes("react/jsx-runtime")) {
      return {
        id: `patch-${diagnostic.file ?? "jsx"}`,
        targetPath: diagnostic.file ? path.normalize(diagnostic.file) : undefined,
        kind: "dependency-install",
        summary: "Install JSX runtime dependencies",
        description: "Add the React JSX runtime packages needed to compile TSX sources.",
        patch: "npm install react react-dom @types/react @types/react-dom",
      };
    }

    if (message.includes("cannot find name") || message.includes("does not exist")) {
      return {
        id: `patch-${diagnostic.file ?? "missing-types"}`,
        targetPath: diagnostic.file ? path.normalize(diagnostic.file) : undefined,
        kind: "file-edit",
        summary: "Add missing type declarations",
        description: "Adjust the generated project configuration for Node and test globals.",
        patch: "",
      };
    }

    return undefined;
  }
}

import fs from "node:fs/promises";
import path from "node:path";
import type { PatchPlan } from "./PatchPlanner.js";
import type { ClassifiedError } from "./ErrorClassifier.js";

export interface GeneratedPatch {
  plan: PatchPlan;
  content?: string;
  filePath?: string;
}

export class PatchGenerator {
  async generate(plans: readonly PatchPlan[], classified: readonly ClassifiedError[], projectRoot: string): Promise<GeneratedPatch[]> {
    const patches: GeneratedPatch[] = [];
    for (const plan of plans) {
      if (plan.kind === "dependency-install") {
        patches.push({ plan, content: plan.patch, filePath: projectRoot });
        continue;
      }

      if (plan.kind === "file-edit") {
        const targetPath = plan.targetPath ? path.resolve(projectRoot, plan.targetPath) : undefined;
        const content = targetPath ? await this.readFile(targetPath) : undefined;
        patches.push({ plan, content, filePath: targetPath });
      }
    }

    for (const error of classified) {
      if (error.category === "typescript-config") {
        const tsconfigPath = path.join(projectRoot, "tsconfig.json");
        const current = await this.readFile(tsconfigPath).catch(() => "{}");
        patches.push({
          plan: {
            id: `tsconfig-${error.diagnostic.code ?? "config"}`,
            kind: "file-edit",
            summary: "Configure TypeScript for JSX and Node testing",
            description: "Ensure TypeScript can compile TSX and Node test files.",
            patch: current,
          },
          content: current,
          filePath: tsconfigPath,
        });
      }
    }

    return patches;
  }

  private async readFile(filePath: string): Promise<string> {
    return fs.readFile(filePath, "utf8").catch(() => "");
  }
}

import fs from "node:fs/promises";
import path from "node:path";
import { CommandExecutor } from "../commands/CommandExecutor.js";
import type { GeneratedPatch } from "./PatchGenerator.js";

export interface PatchApplicationResult {
  applied: boolean;
  filePath?: string;
  reason: string;
}

export class PatchApplier {
  constructor(private readonly executor = new CommandExecutor()) {}

  async apply(patches: readonly GeneratedPatch[], projectRoot: string): Promise<PatchApplicationResult[]> {
    const results: PatchApplicationResult[] = [];
    for (const patch of patches) {
      if (patch.plan.kind === "dependency-install") {
        const result = await this.executor.run("npm", ["install", "react", "react-dom", "@types/react", "@types/react-dom"], { cwd: projectRoot });
        results.push({ applied: result.exitCode === 0, filePath: projectRoot, reason: result.exitCode === 0 ? "Dependency install completed." : result.stderr || result.stdout });
        continue;
      }

      if (patch.filePath) {
        const resolved = path.resolve(projectRoot, patch.filePath);
        await fs.mkdir(path.dirname(resolved), { recursive: true });
        await fs.writeFile(resolved, patch.content ?? "", "utf8");
        results.push({ applied: true, filePath: resolved, reason: "File updated." });
      }
    }
    return results;
  }
}

export interface RetryPolicy {
  maxAttempts: number;
  retryDelayMs: number;
}

export class DefaultRetryPolicy implements RetryPolicy {
  readonly maxAttempts = 4;
  readonly retryDelayMs = 0;
}

import type { Context } from "../core/Context.js";
import type { TestMetrics } from "../ai/engines/TestEngine.js";
import { VerificationEngine } from "./VerificationEngine.js";
import type { CompileResult } from "./CompileResult.js";

export interface BuildVerificationResult {
  compilePassed: boolean;
  testsPassed: boolean;
  verificationPassed: boolean;
  summary: string;
}

export class BuildVerifier {
  constructor(private readonly verificationEngine: VerificationEngine = new VerificationEngine()) {}

  async verify(context: Context, compileResult: CompileResult): Promise<BuildVerificationResult> {
    await this.verificationEngine.run(context);
    const verification = context.verification as { passed?: boolean } | undefined;
    const testsPassed = this.readTestsPassed(context);
    const buildPassed = compileResult.succeeded && testsPassed && (verification?.passed ?? false);
    return {
      compilePassed: compileResult.succeeded,
      testsPassed,
      verificationPassed: verification?.passed ?? false,
      summary: buildPassed ? "Build verified" : "Build verification failed",
    };
  }

  private readTestsPassed(context: Context): boolean {
    const testMetrics = (context.metadata as { test?: TestMetrics } | undefined)?.test;
    if (!testMetrics) {
      return false;
    }

    const exitCodes = [testMetrics.unitExitCode, testMetrics.integrationExitCode];
    return exitCodes.every((exitCode) => exitCode === 0);
  }
}
